// De import registreert de elementen; zonder VlMapLayerCircleStyle tekent de kaartlaag het punt niet.
import {
    VlMap,
    VlMapBaseLayerGRBGray,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
} from '@domg-wc/map';

// De vl-map-features-layer krijgt haar features als GeoJSON-object, in Lambert 72 (EPSG:31370): een punt, een lijn
// en een polygoon. De setter zet het object als JSON-string in het attribuut features.
document.querySelector('vl-map-features-layer').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 1,
            geometry: { type: 'Point', coordinates: [210000, 190000] },
        },
        {
            type: 'Feature',
            id: 2,
            geometry: {
                type: 'LineString',
                coordinates: [
                    [170000, 170000],
                    [150000, 206000],
                ],
            },
        },
        {
            type: 'Feature',
            id: 3,
            geometry: {
                type: 'Polygon',
                coordinates: [
                    [
                        [44000, 171000],
                        [100000, 171000],
                        [100000, 205000],
                        [44000, 205000],
                        [44000, 171000],
                    ],
                ],
            },
        },
    ],
};
